<?php
declare(strict_types=1);require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';require_once __DIR__.'/includes/auth.php';$db=db();$id=(int)($_GET['id']??$_POST['id']??0);if($id<1){http_response_code(404);exit('Lead not found.');}$allowedStatus=['new','contacted','proposal','won','lost'];$allowedPriority=['low','normal','high'];$types=['note','call','email','whatsapp','meeting','proposal','status_change','follow_up'];$msg='';$error='';$stmt=$db->prepare('SELECT * FROM leads WHERE id=? LIMIT 1');$stmt->execute([$id]);$lead=$stmt->fetch();if(!$lead){http_response_code(404);exit('Lead not found.');}
if($_SERVER['REQUEST_METHOD']==='POST'){$action=(string)($_POST['action']??'');if($action==='save_pipeline'){$status=(string)($_POST['status']??'new');$priority=(string)($_POST['priority']??'normal');$assigned=trim((string)($_POST['assigned_to']??''));$follow=trim((string)($_POST['follow_up_at']??''));$value=trim((string)($_POST['estimated_value']??''));$lost=trim((string)($_POST['lost_reason']??''));$notes=trim((string)($_POST['notes']??''));if(!in_array($status,$allowedStatus,true)||!in_array($priority,$allowedPriority,true))$error='Invalid status or priority.';elseif($value!==''&&!is_numeric($value))$error='Estimated value must be numeric.';else{$followAt=$follow!==''?str_replace('T',' ',$follow).':00':null;$now=date('Y-m-d H:i:s');$contacted=$status!=='new'?($lead['contacted_at']?:$now):$lead['contacted_at'];$proposal=$status==='proposal'||$status==='won'?($lead['proposal_at']?:$now):$lead['proposal_at'];$won=$status==='won'?($lead['won_at']?:$now):$lead['won_at'];$db->prepare('UPDATE leads SET status=?,priority=?,assigned_to=?,follow_up_at=?,estimated_value=?,lost_reason=?,notes=?,contacted_at=?,proposal_at=?,won_at=? WHERE id=?')->execute([$status,$priority,$assigned?:null,$followAt,$value!==''?(float)$value:null,$status==='lost'?($lost?:null):null,$notes?:null,$contacted,$proposal,$won,$id]);if($status!==$lead['status']){$a=$db->prepare('INSERT INTO lead_activities (lead_id,activity_type,subject,description) VALUES (?,?,?,?)');$a->execute([$id,'status_change','Status changed','Status changed from '.$lead['status'].' to '.$status]);}$msg='Lead pipeline updated.';}}
elseif($action==='add_activity'){$type=(string)($_POST['activity_type']??'note');$subject=trim((string)($_POST['subject']??''));$description=trim((string)($_POST['description']??''));$follow=trim((string)($_POST['activity_follow_up_at']??''));if(!in_array($type,$types,true))$error='Invalid activity type.';elseif($description===''&&$subject==='')$error='Add a subject or description.';else{$followAt=$follow!==''?str_replace('T',' ',$follow).':00':null;$db->prepare('INSERT INTO lead_activities (lead_id,activity_type,subject,description,follow_up_at) VALUES (?,?,?,?,?)')->execute([$id,$type,$subject?:null,$description?:null,$followAt]);if($followAt)$db->prepare('UPDATE leads SET follow_up_at=? WHERE id=?')->execute([$followAt,$id]);$msg='Activity added.';}}
elseif($action==='delete_activity'){$aid=(int)($_POST['activity_id']??0);if($aid>0){$db->prepare('DELETE FROM lead_activities WHERE id=? AND lead_id=?')->execute([$aid,$id]);$msg='Activity deleted.';}}
$stmt=$db->prepare('SELECT * FROM leads WHERE id=? LIMIT 1');$stmt->execute([$id]);$lead=$stmt->fetch();}
$activities=$db->prepare('SELECT * FROM lead_activities WHERE lead_id=? ORDER BY created_at DESC,id DESC');$activities->execute([$id]);$activities=$activities->fetchAll();$esc=static fn($v):string=>htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');$dt=static function($v):string{return $v?date('d M Y, H:i',strtotime((string)$v)):'—';};$followInput=!empty($lead['follow_up_at'])?date('Y-m-d\TH:i',strtotime($lead['follow_up_at'])):'';?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=$esc($lead['name'])?> | Lead CRM</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>.timeline{border-left:3px solid #dee2e6;padding-left:1.25rem}.activity{position:relative}.activity:before{content:'';position:absolute;left:-1.65rem;top:.4rem;width:12px;height:12px;background:#212529;border-radius:50%}</style></head><body class="bg-light"><main class="container py-5" style="max-width:1150px"><div class="d-flex justify-content-between align-items-center mb-4"><div><h1 class="h2 mb-1"><?=$esc($lead['name'])?></h1><p class="text-muted mb-0">Lead #<?=$id?> · <?=$esc($lead['email'])?></p></div><a href="leads.php" class="btn btn-outline-dark">Back to Leads</a></div><?php if($msg):?><div class="alert alert-success"><?=$esc($msg)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=$esc($error)?></div><?php endif;?><div class="row g-4"><div class="col-lg-7"><div class="card border-0 shadow-sm p-4 mb-4"><h2 class="h5">Enquiry</h2><dl class="row mt-3"><dt class="col-sm-4">Name</dt><dd class="col-sm-8"><?=$esc($lead['name'])?></dd><dt class="col-sm-4">Email</dt><dd class="col-sm-8"><a href="mailto:<?=$esc($lead['email'])?>"><?=$esc($lead['email'])?></a></dd><dt class="col-sm-4">Phone</dt><dd class="col-sm-8"><?=$esc($lead['phone']?:'—')?></dd><dt class="col-sm-4">Company</dt><dd class="col-sm-8"><?=$esc($lead['company']?:'—')?></dd><dt class="col-sm-4">Service</dt><dd class="col-sm-8"><?=$esc($lead['service']?:'—')?></dd><dt class="col-sm-4">Budget</dt><dd class="col-sm-8"><?=$esc($lead['budget']?:'—')?></dd><dt class="col-sm-4">Timeline</dt><dd class="col-sm-8"><?=$esc($lead['timeline']?:'—')?></dd><dt class="col-sm-4">Created</dt><dd class="col-sm-8"><?=$esc($dt($lead['created_at']))?></dd></dl><hr><h3 class="h6">Project message</h3><p class="text-secondary mb-0"><?=nl2br($esc($lead['message']))?></p></div><div class="card border-0 shadow-sm p-4"><div class="d-flex justify-content-between align-items-center"><h2 class="h5 mb-0">Activity Timeline</h2><span class="badge text-bg-dark"><?=count($activities)?></span></div><hr><div class="timeline"><?php if(!$activities):?><p class="text-muted">No activity recorded yet.</p><?php endif;?><?php foreach($activities as $a):?><div class="activity mb-4"><div class="d-flex justify-content-between gap-3"><div><span class="badge text-bg-light border"><?=ucfirst(str_replace('_',' ',$a['activity_type']))?></span><strong class="ms-2"><?=$esc($a['subject']?:'Activity')?></strong></div><small class="text-muted"><?=$esc($dt($a['created_at']))?></small></div><?php if($a['description']):?><p class="mt-2 mb-1 text-secondary"><?=nl2br($esc($a['description']))?></p><?php endif;?><?php if($a['follow_up_at']):?><small class="text-primary">Follow-up: <?=$esc($dt($a['follow_up_at']))?></small><?php endif;?><form method="post" class="mt-2" onsubmit="return confirm('Delete this activity?')"><input type="hidden" name="action" value="delete_activity"><input type="hidden" name="activity_id" value="<?=$a['id']?>"><button class="btn btn-sm btn-link text-danger p-0">Delete</button></form></div><?php endforeach;?></div></div></div><div class="col-lg-5"><div class="card border-0 shadow-sm p-4 mb-4"><h2 class="h5">Pipeline</h2><form method="post" class="mt-3"><input type="hidden" name="action" value="save_pipeline"><input type="hidden" name="id" value="<?=$id?>"><label class="form-label">Status</label><select name="status" class="form-select mb-3"><?php foreach($allowedStatus as $s):?><option value="<?=$s?>" <?=$lead['status']===$s?'selected':''?>><?=ucfirst($s)?></option><?php endforeach;?></select><label class="form-label">Priority</label><select name="priority" class="form-select mb-3"><?php foreach($allowedPriority as $p):?><option value="<?=$p?>" <?=$lead['priority']===$p?'selected':''?>><?=ucfirst($p)?></option><?php endforeach;?></select><label class="form-label">Assigned To</label><input name="assigned_to" class="form-control mb-3" value="<?=$esc($lead['assigned_to'])?>"><label class="form-label">Next Follow-up</label><input type="datetime-local" name="follow_up_at" class="form-control mb-3" value="<?=$esc($followInput)"><label class="form-label">Estimated Value</label><input type="number" step="0.01" min="0" name="estimated_value" class="form-control mb-3" value="<?=$esc($lead['estimated_value'])?>"><label class="form-label">Lost Reason</label><input name="lost_reason" class="form-control mb-3" value="<?=$esc($lead['lost_reason'])?>"><label class="form-label">Internal Notes</label><textarea name="notes" rows="5" class="form-control mb-3"><?=$esc($lead['notes'])?></textarea><button class="btn btn-dark w-100">Save Pipeline</button></form></div><div class="card border-0 shadow-sm p-4"><h2 class="h5">Add Activity</h2><form method="post"><input type="hidden" name="action" value="add_activity"><input type="hidden" name="id" value="<?=$id?>"><label class="form-label">Type</label><select name="activity_type" class="form-select mb-3"><?php foreach($types as $t):?><option value="<?=$t?>"><?=ucfirst(str_replace('_',' ',$t))?></option><?php endforeach;?></select><label class="form-label">Subject</label><input name="subject" class="form-control mb-3"><label class="form-label">Description</label><textarea name="description" rows="4" class="form-control mb-3"></textarea><label class="form-label">Follow-up Date</label><input type="datetime-local" name="activity_follow_up_at" class="form-control mb-3"><button class="btn btn-outline-dark w-100">Add Activity</button></form></div></div></div></main></body></html>